/**
 * Render a Lucide icon as an inline SVG string.
 * @param {string} name
 * @param {number} [size=20]
 * @param {string} [cls='']
 */
export function icon(name, size = 20, cls = '') {
  const body = P[name] || P.info;
  return `<svg class="ic ${cls}" width="${size}" height="${size}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true" focusable="false">${body}</svg>`;
}

/** Godavari Command mark: temple gopuram over river waves. */
export function logo(size = 32) {
  return `<svg class="logo" width="${size}" height="${size}" viewBox="0 0 32 32" aria-hidden="true" focusable="false">
    <rect width="32" height="32" rx="7" fill="rgba(255,255,255,0.10)"/>
    <path d="M16 4.5 L19 9 H13 Z M12 10 H20 L21.5 14 H10.5 Z M9.5 15 H22.5 L24 19.5 H8 Z" fill="#FFFFFF"/>
    <path d="M5 23.5c1.5 1 3 1 4.5 0s3-1 4.5 0 3 1 4.5 0 3-1 4.5 0 3 1 4.5 0" stroke="#7DD3FC" stroke-width="1.6" fill="none" stroke-linecap="round"/>
    <path d="M7 27c1.5 1 3 1 4.5 0s3-1 4.5 0 3 1 4.5 0 3-1 4.5 0" stroke="#7DD3FC" stroke-opacity=".6" stroke-width="1.6" fill="none" stroke-linecap="round"/>
  </svg>`;
}
